const MAX_RANGE_MEMBERS = 1000;

function toSafeInt(token) {
  const n = Number(token);
  if (!Number.isSafeInteger(n)) {
    throw new RangeError(`Integer out of safe range: ${token}`);
  }
  // Normalize -0 to 0
  return n === 0 ? 0 : n;
