export function parseRanges(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseRanges expects a string');
  }
  if (text.trim() === '') {
    return [];
  }

  const seen = new Set();
  const items = text.split(',');

  for (const raw of items) {
    const item = raw.trim();
    if (item === '') {
      throw new RangeError('Empty item in list');
    }

    const m = RANGE_RE.exec(item);
    if (m) {
      const a = toSafeInt(m[1]);
      const b = toSafeInt(m[2]);
      if (a > b) {
        throw new RangeError(`Descending range: ${item}`);
      }
      if (b - a + 1 > MAX_RANGE_MEMBERS) {
        throw new RangeError(`Range has more than ${MAX_RANGE_MEMBERS} members: ${item}`);
