        seen.add(n === 0 ? 0 : n);
      }
    } else if (INT_RE.test(item)) {
      seen.add(toSafeInt(item));
    } else {
      throw new RangeError(`Malformed item: ${item}`);
    }
  }

  return Array.from(seen).sort((x, y) => x - y);
}

