  function readTransfer(transfer) {
    if (transfer === null || typeof transfer !== 'object') {
      throw new RangeError('Transfer must be an object');
    }
    const id = transfer.id;
    const from = transfer.from;
    const to = transfer.to;
    const amount = transfer.amount;
    if (typeof id !== 'string' || id.length === 0) {
      throw new RangeError('Transfer id must be a nonempty string');
    }
    if (typeof from !== 'string' || !balances.has(from)) {
      throw new RangeError(`Unknown source account ${String(from)}`);
    }
    if (typeof to !== 'string' || !balances.has(to)) {
      throw new RangeError(`Unknown destination account ${String(to)}`);
    }
    if (!Number.isSafeInteger(amount) || amount <= 0) {
      throw new RangeError('Transfer amount must be a positive safe integer');
    }
    return { id, from, to, amount };
  }

  function apply(batch) {
    if (!Array.isArray(batch)) {
      throw new RangeError('Batch must be an array');
    }

    const pendingBalances = new Map();
    const pendingIds = new Map();
    const getBalance = (name) =>
      pendingBalances.has(name) ? pendingBalances.get(name) : balances.get(name);

    const results = [];
