    while (j < c.length && c[j][1] <= cur) j++;
    let k = j;
    while (k < c.length && c[k][0] < bEnd) {
      const [cStart, cEnd] = c[k];
      if (cStart > cur) result.push([cur, cStart]);
      if (cEnd > cur) cur = cEnd;
      if (cur >= bEnd) break;
      k++;
    }
    if (cur < bEnd) result.push([cur, bEnd]);
  }
  return result;
}

function fail(message) {
  throw new RangeError(message);
}

function normalize(list, name) {
  if (!Array.isArray(list)) {
    fail(name + ' must be an array of [start, end] pairs');
  }
  const items = [];
  for (let i = 0; i < list.length; i++) {
    const pair = list[i];
    if (!Array.isArray(pair) || pair.length !== 2) {
      fail(name + '[' + i + '] must be a [start, end] pair');
    }
    const start = pair[0];
    const end = pair[1];
    if (
      typeof start !== 'number' ||
      typeof end !== 'number' ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      fail(name + '[' + i + '] endpoints must be finite numbers');
    }
    if (start > end) {
      fail(name + '[' + i + '] start must be <= end');
    }
    if (start < end) {
      items.push([start, end]);
    }
  }
  items.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const last = merged.length ? merged[merged.length - 1] : null;
    if (last !== null && item[0] <= last[1]) {
      if (item[1] > last[1]) {
        last[1] = item[1];
      }
    } else {
      merged.push([item[0], item[1]]);
    }
  }
  return merged;
}

export function subtractIntervals(base, cuts) {
  const b = normalize(base, 'base');
  const c = normalize(cuts, 'cuts');
  const result = [];
  let j = 0;
  for (let i = 0; i < b.length; i++) {
    const start = b[i][0];
    const end = b[i][1];
    let cur = start;
    while (j < c.length && c[j][1] <= cur) {
      j++;
    }
    let k = j;
    while (k < c.length && c[k][0] < end) {
      if (c[k][0] > cur) {
        result.push([cur, c[k][0]]);
      }
      if (c[k][1] > cur) {
        cur = c[k][1];
      }
      if (cur >= end) {
        break;
      }
      k++;
    }
    if (cur < end) {
      result.push([cur, end]);
    }
    j = k;
  }
  return result;
}
